<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import { useRoute } from 'vue-router';import { AlertTriangle,Eye,FileWarning } from 'lucide-vue-next';import ResourceState from '@/components/common/ResourceState.vue';import AlarmDetailDialog from './AlarmDetailDialog.vue';import { getAlarms,getRectifications,issueRectification,reviewRectification,type AlarmRecordRaw,type Rectification } from '@/api/alarm';import { ElMessage,type FormInstance,type FormRules } from 'element-plus'
const route=useRoute();const tab=ref('alarms'),data=ref<AlarmRecordRaw[]>([]),rectifications=ref<Rectification[]>([]),loading=ref(false),error=ref(''),page=ref(1),size=ref(10),type=ref(''),level=ref(''),status=ref(''),projectId=ref(''),deviceId=ref(String(route.query.deviceId||'')),detailDialog=ref(false),selected=ref<AlarmRecordRaw>(),issueDialog=ref(false),reviewDialog=ref(false),selectedRect=ref<Rectification>(),saving=ref(false),formRef=ref<FormInstance>();const issue=ref({alarmId:0,title:'',content:'',deadlineAt:''}),review=ref({approved:true,reviewRemark:''});const rules:FormRules={title:[{required:true,message:'请输入整改标题'}],content:[{required:true,message:'请输入整改内容'}],deadlineAt:[{required:true,message:'请选择截止时间'}],reviewRemark:[{required:true,message:'请输入复查意见'}]};const filtered=computed(()=>data.value.filter(x=>(!type.value||x.alarmType===type.value)&&(!level.value||x.alarmLevel===level.value)&&(!status.value||x.alarmStatus===status.value)&&(!projectId.value||String(x.projectId)===projectId.value)&&(!deviceId.value||String(x.deviceId)===deviceId.value)));const rows=computed(()=>filtered.value.slice((page.value-1)*size.value,page.value*size.value));const load=async()=>{loading.value=true;error.value='';try{const [a,r]=await Promise.all([getAlarms(),getRectifications()]);data.value=a.data;rectifications.value=r.data}catch(e){error.value=e instanceof Error?e.message:'网络异常'}finally{loading.value=false}};const openIssue=(row:AlarmRecordRaw)=>{issue.value={alarmId:row.id,title:`关于${row.alarmTitle}的整改通知`,content:row.alarmContent,deadlineAt:''};issueDialog.value=true};const saveIssue=async()=>{if(!await formRef.value?.validate())return;saving.value=true;try{await issueRectification(issue.value);ElMessage.success('整改通知已下发');issueDialog.value=false;await load()}finally{saving.value=false}};const openReview=(row:Rectification)=>{selectedRect.value=row;review.value={approved:true,reviewRemark:''};reviewDialog.value=true};const saveReview=async()=>{if(!await formRef.value?.validate())return;saving.value=true;try{await reviewRectification(selectedRect.value!.id,review.value);ElMessage.success('整改复查完成');reviewDialog.value=false;await load()}finally{saving.value=false}};onMounted(load)
</script>
<template><article class="tech-panel"><div class="panel-head"><h2 class="panel-title">统一报警与整改中心</h2><div class="tabs"><button :class="{active:tab==='alarms'}" @click="tab='alarms'">报警记录</button><button :class="{active:tab==='rectifications'}" @click="tab='rectifications'">整改通知</button></div></div><template v-if="tab==='alarms'"><div class="resource-toolbar"><el-input v-model="projectId" clearable placeholder="项目ID"/><el-input v-model="deviceId" clearable placeholder="设备ID"/><el-select v-model="type" clearable placeholder="报警类型"><el-option v-for="v in [...new Set(data.map(x=>x.alarmType))]" :key="v" :label="v" :value="v"/></el-select><el-select v-model="level" clearable placeholder="报警等级"><el-option label="提示" value="LOW"/><el-option label="一般" value="MEDIUM"/><el-option label="严重" value="HIGH"/><el-option label="紧急" value="CRITICAL"/></el-select><el-select v-model="status" clearable placeholder="处理状态"><el-option label="未处理" value="PENDING"/><el-option label="处理中" value="HANDLING"/><el-option label="已处理" value="RESOLVED"/><el-option label="已关闭" value="CLOSED"/></el-select><button class="tech-button secondary" @click="load">查询</button></div><ResourceState :loading="loading" :error="error" :empty="!rows.length" @retry="load"><el-table :data="rows"><el-table-column prop="alarmNo" label="报警编号" min-width="150"/><el-table-column prop="alarmTitle" label="报警标题" min-width="180"/><el-table-column prop="alarmType" label="类型"/><el-table-column prop="alarmLevel" label="等级"><template #default="{row}"><span :class="`alarm-${row.alarmLevel}`">{{ row.alarmLevel }}</span></template></el-table-column><el-table-column label="当前值/阈值"><template #default="{row}">{{ row.actualValue??'—' }} / {{ row.thresholdValue??'—' }}</template></el-table-column><el-table-column prop="alarmStatus" label="状态"/><el-table-column prop="triggeredAt" label="发生时间" min-width="165"/><el-table-column label="操作" width="190" fixed="right"><template #default="{row}"><el-button link @click="selected=row;detailDialog=true"><Eye :size="13"/>详情处置</el-button><el-button link @click="openIssue(row)"><FileWarning :size="13"/>下发整改</el-button></template></el-table-column></el-table><div class="resource-pagination"><span>共 {{ filtered.length }} 条报警</span><el-pagination v-model:current-page="page" v-model:page-size="size" layout="prev,pager,next,sizes" :total="filtered.length"/></div></ResourceState></template><template v-else><ResourceState :loading="loading" :error="error" :empty="!rectifications.length" @retry="load"><el-table :data="rectifications"><el-table-column prop="orderNo" label="整改单号"/><el-table-column prop="title" label="标题" min-width="190"/><el-table-column prop="projectId" label="项目ID"/><el-table-column prop="deadlineAt" label="截止时间"/><el-table-column prop="status" label="状态"/><el-table-column prop="resultDescription" label="整改结果"/><el-table-column label="操作"><template #default="{row}"><el-button link @click="openReview(row)">复查</el-button></template></el-table-column></el-table></ResourceState></template></article><AlarmDetailDialog v-model="detailDialog" :alarm="selected" @updated="load"/><el-dialog v-model="issueDialog" title="下发整改通知" width="min(620px,92vw)"><el-form ref="formRef" :model="issue" :rules="rules" label-width="90px"><el-form-item label="整改标题" prop="title"><el-input v-model="issue.title"/></el-form-item><el-form-item label="整改内容" prop="content"><el-input v-model="issue.content" type="textarea"/></el-form-item><el-form-item label="截止时间" prop="deadlineAt"><el-date-picker v-model="issue.deadlineAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item></el-form><template #footer><button class="tech-button" :disabled="saving" @click="saveIssue">确认下发</button></template></el-dialog><el-dialog v-model="reviewDialog" title="整改复查" width="min(580px,92vw)"><el-form ref="formRef" :model="review" :rules="rules" label-width="90px"><el-form-item label="复查结果"><el-switch v-model="review.approved" active-text="通过" inactive-text="不通过"/></el-form-item><el-form-item label="复查意见" prop="reviewRemark"><el-input v-model="review.reviewRemark" type="textarea"/></el-form-item></el-form><template #footer><button class="tech-button" :disabled="saving" @click="saveReview">提交复查</button></template></el-dialog></template>
<style scoped>.tabs{display:flex;gap:5px}.tabs button{padding:6px 9px;border:1px solid rgba(79,168,255,.14);border-radius:4px;color:#7897b4;background:rgba(18,52,91,.3)}.tabs button.active{color:#fff;border-color:#278df5;background:rgba(22,119,255,.25)}.resource-toolbar{display:grid;grid-template-columns:.7fr .7fr repeat(3,1fr) auto;gap:7px;padding:12px}.resource-pagination{display:flex;justify-content:space-between;padding:10px;color:#6f8da9}.alarm-HIGH,.alarm-CRITICAL{color:#ff6378}.alarm-MEDIUM{color:#ffae42}.alarm-LOW{color:#4eaaff}@media(max-width:900px){.resource-toolbar{grid-template-columns:repeat(2,1fr)}}</style>
